"""Read an agent project's behavior settings from `agent.yml`."""

from collections.abc import Mapping
from pathlib import Path
from typing import Optional

from rasa.builder.models import AgentBehavior, BehaviorResponse
from rasa.builder.project_generator.project_utils import strip_project_folder
from rasa.exceptions import ValidationError
from rasa.mantle.config.agent_spec import agent_spec_from_config
from rasa.shared.exceptions import FileIOException, YamlException
from rasa.shared.project_structure import MANTLE_AGENT_FILE
from rasa.shared.utils.yaml import read_yaml_file


def read_agent_behavior(project_folder: Path) -> BehaviorResponse:
    """Parse `agent.yml` the way `rasa train` does and return its behavior settings.

    The file is validated with the same parser training uses, but never
    written: training validation fills in a missing `agent.id` on disk, which
    a read must not do.

    Args:
        project_folder: The agent project folder holding `agent.yml`.

    Returns:
        The behavior settings, or the reason `agent.yml` fails to load, together
        with the file's raw text (`None` when the file is missing or not UTF-8).
    """
    agent_path = project_folder / MANTLE_AGENT_FILE
    if not agent_path.is_file():
        return BehaviorResponse(
            behavior=None,
            error=f"'{MANTLE_AGENT_FILE}' is missing.",
            content=None,
        )

    content = _read_content(agent_path)
    try:
        # Skip the cache: the file is edited between requests.
        raw = read_yaml_file(agent_path, expand_env_vars=False, skip_cache=True)
        if not isinstance(raw, Mapping):
            return BehaviorResponse(
                behavior=None,
                error=f"'{MANTLE_AGENT_FILE}' must contain a YAML mapping.",
                content=content,
            )
        spec = agent_spec_from_config(raw)
    except (YamlException, FileIOException, ValidationError) as exc:
        return BehaviorResponse(
            behavior=None,
            error=strip_project_folder(str(exc), project_folder),
            content=content,
        )

    return BehaviorResponse(
        behavior=AgentBehavior(
            language=spec.language,
            persona=spec.persona,
            rules=list(spec.rules),
            text_rules=spec.orchestrator.text_rules,
            voice_rules=spec.orchestrator.voice_rules,
            routing_no_active_skill=spec.prompts.routing_no_active_skill,
        ),
        error=None,
        content=content,
    )


def _read_content(agent_path: Path) -> Optional[str]:
    """Return the raw text of *agent_path*, or None if it is not UTF-8 text."""
    try:
        return agent_path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None
